class Solution:
    def countCollisions(self, directions: str) -> int:
        s = directions.lstrip("L").rstrip("R")
        return len(s) - s.count("S")

class Solution {
public:
    int countCollisions(string directions) {
        int n = directions.size();
        int l = 0, r = n - 1;
        while (l < n && directions[l] == 'L') l++;
        while (r >= 0 && directions[r] == 'R') r--;
        int ans = 0;
        for (int i = l; i <= r; i++) {
            if (directions[i] != 'S') ans++;
        }
        return ans;
    }
};

class Solution {
    public int countCollisions(String directions) {
        int n = directions.length();
        int l = 0, r = n - 1;
        while (l < n && directions.charAt(l) == 'L') l++;
        while (r >= 0 && directions.charAt(r) == 'R') r--;
        int ans = 0;
        for (int i = l; i <= r; i++) {
            if (directions.charAt(i) != 'S') ans++;
        }
        return ans;
    }
}

